<template><div><div class="page-title"><div><h1>出勤与工时统计</h1><p>按月汇总出勤天数、各类班次与夜班加班时长。</p></div><el-button @click="exportExcel">导出统计表</el-button></div><el-card><div class="filters"><el-date-picker v-model="month" type="month" value-format="YYYY-MM"/><el-button @click="load">查询</el-button></div><el-table :data="rows"><el-table-column prop="name" label="人员"/><el-table-column prop="attendance_days" label="出勤天数"/><el-table-column prop="day_shifts" label="白班"/><el-table-column prop="evening_shifts" label="中班"/><el-table-column prop="night_shifts" label="夜班"/><el-table-column prop="overtime_hours" label="加班时长(h)"/></el-table></el-card></div></template>
<script setup lang="ts">
import {onMounted, ref} from 'vue'; import {ElMessage} from 'element-plus'; import api from '../api/http'
const month=ref(new Date().toISOString().slice(0,7)),rows=ref<any[]>([]);async function load(){rows.value=await api.get('/schedules/statistics',{params:{department_id:1,month:month.value}})};async function exportExcel(){try{const token=localStorage.getItem('gbsched_token')||'';const res=await fetch(`/api/v1/schedules/export?department_id=1&month=${month.value}`,{headers:{Authorization:`Bearer ${token}`}});if(!res.ok){throw new Error('导出失败')}const blob=await res.blob();const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`排班统计-${month.value}.xlsx`;link.click();URL.revokeObjectURL(link.href);ElMessage.success('统计文件已导出')}catch(error:any){ElMessage.error(error.message||'导出失败')}};onMounted(load)
</script>